"""Test GF(2) linearity of h2 from lin probes and characterize length limit."""
import json
from pathlib import Path

ROOT = Path(r"<G5A_WORKDIR>")
rows = [json.loads(l) for l in (ROOT / '_work/t1/lin_h2.jsonl').read_text(encoding='utf-8').splitlines()]

def h2of(r):
    if r['rc'] != 0 or not r['out'].split():
        return None
    try:
        return int(r['out'].split()[1])
    except (ValueError, IndexError):
        return None

H = {}
for r in rows:
    h = h2of(r)
    if h is not None:
        H[r['name']] = (bytes.fromhex(r['stdin_hex']), h)

h_empty = H['empty'][1]
print('h(empty) =', h_empty)

# single byte table
sb = {}
for name, (b, h) in H.items():
    if name.startswith('b') and len(b) == 1:
        sb[b[0]] = h
missing = [c for c in range(0x100) if c not in sb]
print('single-byte entries:', len(sb), 'missing (rc!=0):', [hex(c) for c in missing])

# GF(2) linearity: L(c) = h(c) ^ h(empty); check L(c1^c2) == L(c1)^L(c2)
bad = 0
tested = 0
for c1 in range(0x100):
    for c2 in range(0x100):
        c3 = c1 ^ c2
        if c1 in sb and c2 in sb and c3 in sb:
            L1 = sb[c1] ^ h_empty
            L2 = sb[c2] ^ h_empty
            L3 = sb[c3] ^ h_empty
            tested += 1
            if (L1 ^ L2) != L3:
                bad += 1
                if bad <= 5:
                    print(f'  NONLINEAR: c1={c1:02x} c2={c2:02x} c3={c3:02x} L1^L2={L1^L2:#010x} L3={L3:#010x}')
print(f'GF(2) single-byte linearity: {tested} tests, {bad} violations')

# two-byte with trailing zero: check extension: h(c,0) vs linear combo?
tb = {}
for name, (b, h) in H.items():
    if name.startswith('bb') and len(b) == 2:
        tb[b[0]] = h
print('two-byte entries:', len(tb))
# Test 1: is h(c,0) == f(h(c), 0x00)? unknown f. Instead test: (h(c,0)^h_empty) related to L(c) by constant shift?
consts = set()
for c in range(0x100):
    if c in sb and c in tb:
        consts.add((tb[c] ^ sb[c] ^ h_empty))
print('distinct (h(c,0)^h(c)^h_empty) values:', len(consts), [hex(x) for x in list(consts)[:8]])

# length limit
for name, (b, h) in sorted(H.items()):
    if name.startswith(('a', 'nonl', 'mix')) and not name.startswith(('a' + 'a')):
        pass
for name in [n for n in H if n.startswith('a') or n.startswith('nonl') or n == 'mix']:
    b, h = H[name]
    if h is None:
        print(f'  {name}: len={len(b)} -> rc!=0')
print('a78' in H and f"a78 h={H['a78'][1]:#x}" or 'a78 missing', 'a79' in H and (f"a79 h={H['a79'][1]:#x}" if H['a79'][1] else 'a79 FAILS'))
